 CREATE OR REPLACE FUNCTION public.approverestitutionpayment(approveobj json)                                                                                                                               
  RETURNS text                                                                                                                                                                                              
  LANGUAGE plpgsql                                                                                                                                                                                          
 AS $function$                                                                                                                                                                                            
                                                                                                                                                                                                          
 DECLARE                                                                                                                                                                                                  
         v_paymentjson json;                                                                                                                                                                              
         v_paymentid character varying;                                                                                                                                                                   
         v_paymentuuid  uuid;                                                                                                                                                                             
         v_restitutionno int;                                                                                                                                                                             
         v_memofirstname int;                                                                                                                                                                             
         v_paidamount numeric;                                                                                                                                                                            
         v_givenamount numeric;                                                                                                                                                                           
         v_contentid uuid;                                                                                                                                                                                
         v_intakeserreqrestitutionid uuid;                                                                                                                                                                
         v_status character varying;                                                                                                                                                                      
         i json;                                                                                                                                                                                          
         v_date timestamp without time zone;                                                                                                                                                              
                                                                                                                                                                                                          
                                                                                                                                                                                                          
 BEGIN                                                                                                                                                                                                    
         v_date:= now() at time zone 'utc';                                                                                                                                                               
         v_paymentjson := approveobj ->> 'restitutionpaymentdetails';                                                                                                                                     
         v_contentid := approveobj ->> 'restitutionpaymentflatfilecontentid';                                                                                                                             
         v_status := approveobj ->> 'status';                                                                                                                                                             
                                                                                                                                                                                                          
         IF (lower(v_status) = 'approved') THEN                                                                                                                                                           
                                                                                                                                                                                                          
         FOR i IN SELECT * FROM json_array_elements(v_paymentjson)                                                                                                                                        
         loop                                                                                                                                                                                             
             v_paymentid := (i ->> 'restitutionpaymentdetails');                                                                                                                                          
             v_paymentuuid := (i ->> 'intakeserreqrestitutionpaymentid');                                                                                                                                 
             v_paidamount := (i ->> 'allocatedamount');                                                                                                                                                   
             v_memofirstname := (i ->> 'memofirstname');                                                                                                                                                  
             v_restitutionno := (i ->> 'restitutionno');                                                                                                                                                  
             v_intakeserreqrestitutionid := (i ->> 'intakeserreqrestitutionid');                                                                                                                          
                                                                                                                                                                                                          
             update routing set routingstatustypeid=36,updatedon = v_date where objectid=v_paymentid;                                                                                                     
                                                                                                                                                                                                          
             select paidamount into v_givenamount from intakeserreqrestitution where restitutionno=v_restitutionno and intakeserreqrestitutionid = v_intakeserreqrestitutionid;                           
                                                                                                                                                                                                          
             update intakeserreqrestitution set paidamount=(coalesce(v_givenamount,0)+v_paidamount),allocatedamount = (coalesce(allocatedamount,0) - coalesce(v_paidamount,0)),                           
             updatedon = v_date where restitutionno=v_restitutionno and intakeserreqrestitutionid = v_intakeserreqrestitutionid;                                                                          
                                                                                                                                                                                                          
             update intakeserreqrestitutionpayment set restitutionstatus='Approved' ,updatedon = v_date where intakeserreqrestitutionid=v_paymentuuid and restitutionpaymentflatfilecontentid=v_contentid;
                                                                                                                                                                                                          
                                                                                                                                                                                                          
         END LOOP;                                                                                                                                                                                        
                                                                                                                                                                                                          
         update restitutionpaymentflatfilecontent set status='Approved' ,updatedon = v_date where restitutionpaymentflatfilecontentid=v_contentid;                                                        
                                                                                                                                                                                                          
                                                                                                                                                                                                          
         ELSIF (lower(v_status) = 'refund approved') THEN                                                                                                                                                 
                                                                                                                                                                                                          
         update restitutionpaymentflatfilecontent set refundstatus='Refund Approved',updatedon = v_date  where restitutionpaymentflatfilecontentid=v_contentid;                                           
                                                                                                                                                                                                          
         END IF;                                                                                                                                                                                          
                                                                                                                                                                                                          
                                                                                                                                                                                                          
                                                                                                                                                                                                          
                                                                                                                                                                                                          
                                                                                                                                                                                                          
                                                                                                                                                                                                          
 return 'Success';                                                                                                                                                                                        
                                                                                                                                                                                                          
 END;                                                                                                                                                                                                     
                                                                                                                                                                                                          
 $function$                                                                                                                                                                                                 

